-- Generated by scripts/build_compiled.py from src/fraudrules/rules/foreign-agent/fa-007-agent-withholds-information.yaml. Do not edit.
-- FA-007 Foreign agent ignores or refuses repeated requests for documents or due diligence
SELECT 'FA-007' AS rule_id, 'events' AS anchor_table, a.id AS anchor_id
FROM events AS a
JOIN events AS b ON b.customer_id = a.customer_id AND b.ts <= a.ts AND b.ts > a.ts - 7776000
WHERE (a.event_type = 'agent_info_request' AND a.outcome IN ('failure', 'denied')) AND (b.event_type = 'agent_info_request' AND b.outcome IN ('failure', 'denied'))
GROUP BY a.id
HAVING COUNT(*) >= 2;
